      ctx.save(); ctx.strokeStyle = '#A85440'; ctx.lineWidth = 10; ctx.lineCap = 'round'; ctx.beginPath(); ctx.moveTo(1080, Y + 10); ctx.bezierCurveTo(1110, Y - 30, 1150, Y + 40, 1180, Y); ctx.stroke(); ctx.restore();
